import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { useClipboard } from '../contexts/ClipboardContext';
import { SparklesIcon, ClipboardDocumentIcon } from '@heroicons/react/24/outline';

const SharedClipboard = () => {
  const { link } = useParams();
  const { getSharedClipboard } = useClipboard();
  const [clipboard, setClipboard] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [copyStatus, setCopyStatus] = useState('');

  useEffect(() => {
    const fetchClipboard = async () => {
      try {
        const data = await getSharedClipboard(link);
        setClipboard(data);
      } catch (err) {
        setError('✨ This magic does not exist or is kept secret ✨');
      } finally {
        setLoading(false);
      }
    };

    fetchClipboard();
  }, [link, getSharedClipboard]);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(clipboard.content);
      setCopyStatus('✨ Magic copied! ✨');
      setTimeout(() => setCopyStatus(''), 2000);
    } catch (err) {
      console.error('Failed to copy:', err);
      setCopyStatus('💔 Failed to copy magic');
      setTimeout(() => setCopyStatus(''), 2000);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <div className="animate-spin-slow text-fun-purple">
          <SparklesIcon className="h-16 w-16" />
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="fun-card border-fun-red bg-red-50/50 dark:bg-red-900/50 text-red-600 dark:text-red-200 p-6 mt-8 animate-float" role="alert">
          <span className="block text-center text-lg">{error}</span>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
      <div className="fun-card mt-8 overflow-hidden">
        <div className="p-6">
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center space-y-4 sm:space-y-0">
            <h1 className="fun-title text-2xl sm:text-3xl flex items-center">
              <SparklesIcon className="h-8 w-8 mr-2 animate-spin-slow text-fun-purple" />
              {clipboard.title}
            </h1>
            <button
              onClick={handleCopy}
              className="fun-button group animate-float"
            >
              <ClipboardDocumentIcon className="h-5 w-5 mr-2 inline group-hover:animate-bounce-slow" />
              Copy Magic ✨
            </button>
          </div>
          {copyStatus && (
            <div className="mt-4 text-center text-fun-purple animate-bounce-slow">
              {copyStatus}
            </div>
          )}
          <div className="mt-6">
            <pre className="fun-card !bg-white/50 dark:!bg-dark-card/50 p-6 whitespace-pre-wrap break-words text-gray-600 dark:text-gray-300">
              {clipboard.content}
            </pre>
          </div>
          {clipboard.attachments?.length > 0 && (
            <div className="mt-6 space-y-2">
              <h2 className="fun-title text-xl">✨ Magical Attachments</h2>
              <div className="flex flex-wrap gap-2">
                {clipboard.attachments.map((file, index) => (
                  <a
                    key={index}
                    href={file.url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="fun-button !bg-gradient-party animate-float"
                  >
                    📎 {file.name}
                  </a>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default SharedClipboard;
